  ctx.fillStyle = "#f8fafc";
  ctx.fillRect(0, 0, 256, 256);
  ctx.fillStyle = "#111827";
  ctx.font = "bold 94px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("D", 128, 128);
